    { const char * tb_v1183 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v1183; }
    { const char * tb_v1184 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v1184; }
    { const char * tb_v1185 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1185; }
