    { const char * tb_v1467 = "    long long nbytes, cap;         // большой блок: сколько занято и сколько взято\n"; *(const char * *)tb_grow(v_lines) = tb_v1467; }
    { const char * tb_v1468 = "    unsigned long long inv;        // 2^32 / bsize (вверх): номер блока умножением, без деления\n"; *(const char * *)tb_grow(v_lines) = tb_v1468; }
