    { const char * tb_v1478 = "// адрес → страница: таблица в два шага (биты 47..32, потом 31..16)\n"; *(const char * *)tb_grow(v_lines) = tb_v1478; }
    { const char * tb_v1479 = "TB_API tb_gpage **tb_gdir[1 << 16];\n"; *(const char * *)tb_grow(v_lines) = tb_v1479; }
