    { const char * tb_v2861 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2861; }
    { const char * tb_v2862 = "TB_API void *tb_cold_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2862; }
    { const char * tb_v2863 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2863; }
    { const char * tb_v2864 = "    void *r = tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2864; }
    { const char * tb_v2865 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2865; }
    { const char * tb_v2866 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v2866; }
    { const char * tb_v2867 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2867; }
    { const char * tb_v2868 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2868; }
    { const char * tb_v2869 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v2869; }
    { const char * tb_v2870 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2870; }
    { const char * tb_v2871 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v2871; }
