    { const char * tb_v3087 = "#define TB_TOUCH(a, n) if (TB_RARE(tb_memchk())) tb_mem_touch((uintptr_t)(a), (n), line)\n"; *(const char * *)tb_grow(v_lines) = tb_v3087; }
