    { const char * tb_v3542 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3542; }
    { const char * tb_v3543 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3543; }
