    { const char * tb_v6688 = "TB_API void tb_gfx_events(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6688; }
    { const char * tb_v6689 = "    if (tb_gpu_on) tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6689; }
    { const char * tb_v6690 = "    else XPutImage(tb_dpy, tb_xw, tb_xgc, tb_ximg, 0, 0, 0, 0, tb_gw, tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v6690; }
    { const char * tb_v6691 = "    while (XPending(tb_dpy)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6691; }
