    { const char * tb_v6716 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6716; }
    { const char * tb_v6717 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v6717; }
    { const char * tb_v6718 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v6718; }
    { const char * tb_v6719 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v6719; }
    { const char * tb_v6720 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v6720; }
    { const char * tb_v6721 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v6721; }
    { const char * tb_v6722 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6722; }
    { const char * tb_v6723 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6723; }
    { const char * tb_v6724 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6724; }
    { const char * tb_v6725 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6725; }
    { const char * tb_v6726 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6726; }
    { const char * tb_v6727 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6727; }
    { const char * tb_v6728 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6728; }
    { const char * tb_v6729 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v6729; }
    { const char * tb_v6730 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v6730; }
    { const char * tb_v6731 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v6731; }
    { const char * tb_v6732 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6732; }
    { const char * tb_v6733 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6733; }
    { const char * tb_v6734 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v6734; }
    { const char * tb_v6735 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v6735; }
    { const char * tb_v6736 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v6736; }
    { const char * tb_v6737 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6737; }
    { const char * tb_v6738 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6738; }
    { const char * tb_v6739 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6739; }
    { const char * tb_v6740 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6740; }
    { const char * tb_v6741 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6741; }
    { const char * tb_v6742 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6742; }
    { const char * tb_v6743 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6743; }
    { const char * tb_v6744 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6744; }
    { const char * tb_v6745 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v6745; }
    { const char * tb_v6746 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6746; }
    { const char * tb_v6747 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6747; }
    { const char * tb_v6748 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6748; }
    { const char * tb_v6749 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6749; }
    { const char * tb_v6750 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6750; }
    { const char * tb_v6751 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6751; }
    { const char * tb_v6752 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v6752; }
    { const char * tb_v6753 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6753; }
    { const char * tb_v6754 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6754; }
    { const char * tb_v6755 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6755; }
    { const char * tb_v6756 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6756; }
    { const char * tb_v6757 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6757; }
    { const char * tb_v6758 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6758; }
    { const char * tb_v6759 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v6759; }
    { const char * tb_v6760 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6760; }
    { const char * tb_v6761 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6761; }
    { const char * tb_v6762 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v6762; }
    { const char * tb_v6763 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6763; }
    { const char * tb_v6764 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6764; }
    { const char * tb_v6765 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6765; }
    { const char * tb_v6766 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v6766; }
    { const char * tb_v6767 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6767; }
    { const char * tb_v6768 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6768; }
    { const char * tb_v6769 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6769; }
    { const char * tb_v6770 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6770; }
    { const char * tb_v6771 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6771; }
    { const char * tb_v6772 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v6772; }
    { const char * tb_v6773 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v6773; }
    { const char * tb_v6774 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v6774; }
    { const char * tb_v6775 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6775; }
    { const char * tb_v6776 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6776; }
    { const char * tb_v6777 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6777; }
    { const char * tb_v6778 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6778; }
    { const char * tb_v6779 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6779; }
    { const char * tb_v6780 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6780; }
    { const char * tb_v6781 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v6781; }
    { const char * tb_v6782 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6782; }
    { const char * tb_v6783 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v6783; }
    { const char * tb_v6784 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v6784; }
    { const char * tb_v6785 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6785; }
    { const char * tb_v6786 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6786; }
    { const char * tb_v6787 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6787; }
    { const char * tb_v6788 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6788; }
