    { const char * tb_v6818 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6818; }
    { const char * tb_v6819 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6819; }
