    { const char * tb_v6848 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6848; }
    { const char * tb_v6849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6849; }
    { const char * tb_v6850 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v6850; }
    { const char * tb_v6851 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v6851; }
    { const char * tb_v6852 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v6852; }
    { const char * tb_v6853 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6853; }
    { const char * tb_v6854 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6854; }
    { const char * tb_v6855 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v6855; }
    { const char * tb_v6856 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6856; }
    { const char * tb_v6857 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6857; }
    { const char * tb_v6858 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6858; }
    { const char * tb_v6859 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6859; }
    { const char * tb_v6860 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6860; }
    { const char * tb_v6861 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6861; }
    { const char * tb_v6862 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6862; }
    { const char * tb_v6863 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6863; }
    { const char * tb_v6864 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6864; }
    { const char * tb_v6865 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6865; }
    { const char * tb_v6866 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6866; }
    { const char * tb_v6867 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6867; }
    { const char * tb_v6868 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6868; }
    { const char * tb_v6869 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6869; }
    { const char * tb_v6870 = "    if (TB_CPU_DRAW) tb_cpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6870; }
    { const char * tb_v6871 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6871; }
    { const char * tb_v6872 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6872; }
    { const char * tb_v6873 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6873; }
    { const char * tb_v6874 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6874; }
    { const char * tb_v6875 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v6875; }
    { const char * tb_v6876 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6876; }
    { const char * tb_v6877 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v6877; }
    { const char * tb_v6878 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6878; }
    { const char * tb_v6879 = "            if (i * i + j * j <= r * r + r) tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6879; }
    { const char * tb_v6880 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6880; }
    { const char * tb_v6881 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6881; }
    { const char * tb_v6882 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6882; }
    { const char * tb_v6883 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
    { const char * tb_v6885 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6885; }
    { const char * tb_v6886 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v6886; }
    { const char * tb_v6887 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6887; }
    { const char * tb_v6888 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v6888; }
    { const char * tb_v6889 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6889; }
    { const char * tb_v6890 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v6890; }
    { const char * tb_v6891 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v6891; }
    { const char * tb_v6892 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6892; }
    { const char * tb_v6893 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6893; }
    { const char * tb_v6894 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6894; }
    { const char * tb_v6895 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6895; }
    { const char * tb_v6896 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v6896; }
    { const char * tb_v6897 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6897; }
    { const char * tb_v6898 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v6898; }
    { const char * tb_v6899 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v6899; }
    { const char * tb_v6900 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v6900; }
    { const char * tb_v6901 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v6901; }
    { const char * tb_v6902 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v6902; }
    { const char * tb_v6903 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6903; }
    { const char * tb_v6904 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v6904; }
    { const char * tb_v6905 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6905; }
    { const char * tb_v6906 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6906; }
    { const char * tb_v6907 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6907; }
    { const char * tb_v6908 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6908; }
    { const char * tb_v6909 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6909; }
    { const char * tb_v6910 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6910; }
    { const char * tb_v6911 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6911; }
    { const char * tb_v6912 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6912; }
    { const char * tb_v6913 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6913; }
    { const char * tb_v6914 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6914; }
