    { const char * tb_v6974 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v6974; }
    { const char * tb_v6975 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6975; }
    { const char * tb_v6976 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v6976; }
    { const char * tb_v6977 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6977; }
    { const char * tb_v6978 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
    { const char * tb_v6979 = "            int j = (i + 1) % n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6979; }
    { const char * tb_v6980 = "            double vi = side == 0 ? ax[i] - gx0 : side == 1 ? gx1 - ax[i] : side == 2 ? ay[i] - gy0 : gy1 - ay[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6980; }
    { const char * tb_v6981 = "            double vj = side == 0 ? ax[j] - gx0 : side == 1 ? gx1 - ax[j] : side == 2 ? ay[j] - gy0 : gy1 - ay[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v6981; }
    { const char * tb_v6982 = "            if (vi >= 0) { bx[m] = ax[i]; by[m] = ay[i]; m++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6982; }
    { const char * tb_v6983 = "            if ((vi >= 0) != (vj >= 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6983; }
    { const char * tb_v6984 = "                double k = vi / (vi - vj);\n"; *(const char * *)tb_grow(v_lines) = tb_v6984; }
    { const char * tb_v6985 = "                bx[m] = ax[i] + (ax[j] - ax[i]) * k; by[m] = ay[i] + (ay[j] - ay[i]) * k; m++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6985; }
    { const char * tb_v6986 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6986; }
    { const char * tb_v6987 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6987; }
    { const char * tb_v6988 = "        n = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v6988; }
    { const char * tb_v6989 = "        for (int i = 0; i < n; i++) { ax[i] = bx[i]; ay[i] = by[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6989; }
    { const char * tb_v6990 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6990; }
    { const char * tb_v6991 = "    if (n < 3) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6991; }
    { const char * tb_v6992 = "    long long rx[16], ry[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v6992; }
