    { const char * tb_v7003 = "    for (int i = 0; i < 6; i++) if (t[i] < -8192 || t[i] > 8192) big = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7003; }
    { const char * tb_v7004 = "    if (!big) { tb_tri_draw_i(t, c, 0); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7004; }
