    { const char * tb_v7009 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7009; }
    { const char * tb_v7010 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7010; }
