    { const char * tb_v7205 = "// старый путь (дроби): сетка задевает камеру или край, где целые не годятся — обрезка у камеры и рамкой\n"; *(const char * *)tb_grow(v_lines) = tb_v7205; }
    { const char * tb_v7206 = "TB_API long long *tb_3vst = 0, tb_3vgen = 0;   // какой угол уже посчитан в этом вызове\n"; *(const char * *)tb_grow(v_lines) = tb_v7206; }
    { const char * tb_v7207 = "static void tb_draw_mesh_d(tb_mesh *m, double x, double y, double z, double turn, long long t0, long long t1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7207; }
