    { const char * tb_v7216 = "    double f = tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180), zn = 205.0 / 4096, hw = tb_gw / 2.0, hh = tb_gh / 2.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7216; }
