    { const char * tb_v7265 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7265; }
    { const char * tb_v7266 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7266; }
