    { const char * tb_v7272 = "            sx[i] = hw + f * qx[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7272; }
    { const char * tb_v7273 = "            sy[i] = hh - f * qy[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7273; }
