    { const char * tb_v7422 = "static int tb_kd_cmp(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7422; }
    { const char * tb_v7423 = "    float x = tb_kd_c[3 * *(const uint32_t *)a + tb_kd_ax], y = tb_kd_c[3 * *(const uint32_t *)b + tb_kd_ax];\n"; *(const char * *)tb_grow(v_lines) = tb_v7423; }
