    { const char * tb_v7425 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7425; }
    { const char * tb_v7426 = "static void tb_kd(tb_mesh *m, uint32_t *ix, long long n, const float *cen, long long *at) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7426; }
    { const char * tb_v7427 = "    if (n <= 256) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7427; }
