    { const char * tb_v7563 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7563; }
    { const char * tb_v7564 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7564; }
    { const char * tb_v7565 = "TB_API void tb_clipboard_set(const char *s) { tb_gfx_clip_set(s ? s : \"\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7565; }
    { const char * tb_v7566 = "// вид стрелки мыши над окном\n"; *(const char * *)tb_grow(v_lines) = tb_v7566; }
    { const char * tb_v7567 = "TB_API void tb_set_cursor(const char *name, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7567; }
    { const char * tb_v7568 = "    static const char *names[] = { \"arrow\", \"hand\", \"text\", \"move\", \"resize_x\", \"resize_y\", \"wait\", \"none\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v7568; }
    { const char * tb_v7569 = "    for (int i = 0; i < 8; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7569; }
    { const char * tb_v7570 = "        if (strcmp(name, names[i]) == 0) { if (tb_px) tb_gfx_cursor(i); else tb_cursor_want = i; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7570; }
