    { const char * tb_v8013 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v8013; }
    { const char * tb_v8014 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8014; }
    { const char * tb_v8015 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8015; }
    { const char * tb_v8016 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8016; }
    { const char * tb_v8017 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8017; }
    { const char * tb_v8018 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v8018; }
    { const char * tb_v8019 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8019; }
    { const char * tb_v8020 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v8020; }
    { const char * tb_v8021 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8021; }
    { const char * tb_v8022 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8022; }
    { const char * tb_v8023 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8023; }
    { const char * tb_v8024 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8024; }
    { const char * tb_v8025 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8025; }
    { const char * tb_v8026 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8026; }
    { const char * tb_v8027 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8027; }
    { const char * tb_v8028 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8028; }
