    { const char * tb_v8077 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8077; }
